const std = @import("std");
const vort = @import("vort");
const lib = @import("br_runtime");
pub fn main(init: std.process.Init) !void {
    var args = try std.process.Args.Iterator.initAllocator(init.minimal.args, init.gpa);
    defer args.deinit();
    _ = args.next();
    const path = args.next().?;
    const quality = try std.fmt.parseInt(c_int, args.next().?, 10);
    const payload = try std.Io.Dir.cwd().readFileAlloc(init.io, path, init.gpa, .limited(16 * 1024 * 1024));
    defer init.gpa.free(payload);
    var runtime = try lib.Runtime.open();
    defer runtime.deinit();
    const encoded = try runtime.encodeAlloc(init.gpa, payload, quality);
    defer init.gpa.free(encoded);
    const output = try init.gpa.alloc(u8, payload.len);
    defer init.gpa.free(output);
    vort.br.paired_literal_lookup.audit = .{};
    const n = try vort.brDecodeStreamInto(encoded, output);
    if (n != payload.len or !std.mem.eql(u8, payload, output)) return error.SizeMismatch;
    const a = vort.br.paired_literal_lookup.audit;
    var buf: [2048]u8 = undefined;
    var stdout = std.Io.File.stdout().writerStreaming(init.io, &buf);
    try stdout.interface.print("input={d} encoded={d} quality={d} literals={d} short={d} paired={d} missing_root={d} missing_child={d} long_bits={any}\n", .{payload.len,encoded.len,quality,a.literals,a.short,a.paired,a.missing_root,a.missing_child,a.long_bits});
    try stdout.interface.flush();
}

